  "org.membersMatrixCellEditor.editPopoverTitle": "{username} ਸੋਧੋ",
  "org.membersMatrixView.buildingMatrix": "ਪੋਰਟਫੋਲੀਓ ਮੈਟ੍ਰਿਕਸ ਬਣ ਰਿਹਾ ਹੈ…",
  "org.membersMatrixView.memberColumnHeader": "ਸਦੱਸ",
